const $=s=>document.querySelector(s);
const data=await fetch('catalog.json').then(r=>{if(!r.ok)throw Error('清单载入失败');return r.json()}).catch(e=>{document.querySelector('.notice').textContent=e.message;return {models:[],images:[]}});
const styles=['原神参考 · 赛璐璐','终末地参考 · PBR 动漫','宫崎骏参考 · 水粉','BK 候选 · 未校准','手绘油画候选','Bloomwalker参考 · 柔绘'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#modelCount').textContent=data.models.length;$('#uiCount').textContent=data.images.length;
let active=[],version='all',subject='revised:01',style='all',epoch=0,queue=[],loading=0,observe=null,syncOrbit='35deg 75deg auto',syncFrame=0,syncSource=null;
function shownModels(){return data.models.filter(m=>(version==='all'||m.version===version)&&(subject==='all'||m.version+':'+m.subject_id===subject)&&(style==='all'||m.style_id===style))}
function updateLoadStatus(){const total=shownModels().length;$('#previewStatus').textContent=`${active.filter(x=>x.ready).length} / ${total} 已载入${loading?' · 正在载入':''} · 无并排数量限制`}
function releaseAll(){cancelAnimationFrame(syncFrame);syncFrame=0;syncSource=null;epoch++;queue=[];loading=0;observe?.disconnect();active.forEach(x=>{x.mv.remove();x.stage.querySelector('.load').hidden=false;x.stage.classList.remove('ready');});active=[];updateLoadStatus()}
function drawNavigation(){
 document.querySelectorAll('[data-version]').forEach(b=>{b.classList.toggle('selected',b.dataset.version===version);b.setAttribute('aria-pressed',b.dataset.version===version)});
 let groups=new Map();data.models.filter(m=>version==='all'||m.version===version).forEach(m=>{let k=m.version+':'+m.subject_id;if(!groups.has(k))groups.set(k,{m,n:0});groups.get(k).n++});
 $('#subjectList').innerHTML=`<button data-subject="all" class="subject-button ${subject==='all'?'selected':''}"><span>全部模型</span><small>${data.models.filter(m=>version==='all'||m.version===version).length} 件</small></button>`+[...groups].map(([k,{m,n}])=>`<button data-subject="${esc(k)}" class="subject-button ${subject===k?'selected':''}"><span>${esc(m.subject)}</span><small>${m.version==='prior'?'前版':'新题材'} · ${n} 款</small></button>`).join('');
 document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.subject;drawNavigation();renderModels()});
 $('#styleButtons').innerHTML=`<button data-style="all" class="${style==='all'?'selected':''}">全部风格</button>`+styles.map((s,i)=>`<button data-style="${String(i+1).padStart(2,'0')}" class="${style===String(i+1).padStart(2,'0')?'selected':''}">${esc(s)}</button>`).join('');
 document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{style=b.dataset.style;drawNavigation();renderModels()});
}
function renderModels(){releaseAll();const list=shownModels();$('#viewTitle').textContent=subject==='all'?'全部模型 · 连续浏览':(list[0]?.subject||'暂无模型')+' · 并排比较';
 $('#modelGrid').innerHTML=list.map(m=>`<article class="card"><div class="stage" data-id="${esc(m.id)}"><span class="index">${esc(m.style_id)} / 06</span>${m.preview?`<img class="model-poster" src="${esc(m.preview)}" alt="${esc(m.title)}预览" loading="lazy">`:''}<button class="expand" aria-label="全屏查看模型" title="全屏查看模型">⛶ 放大</button><button class="load">载入实际模型</button><span class="loading-label">正在载入实际 GLB…</span></div><div class="card-body"><h3>${esc(styles[Number(m.style_id)-1]||m.style)}</h3><div class="meta"><span>${Number(m.actual_triangles).toLocaleString()} 三角面</span><span>${(m.bytes/1048576).toFixed(2)} MB</span><span>${esc(m.subject)}</span></div><p><span class="badge">${m.version==='prior'?'前版保留对照':'风格未通过 · 待重做'}</span> ${m.uncalibrated?'BK 未校准':''} · 图集存在复用</p><a href="${esc(m.file)}" download>下载 GLB</a><details><summary>文件与材质核验</summary><p>SHA256 ${esc(m.sha256)}<br>清单匹配：${m.manifest_hash_verified?'已核对':'未确认'} · ${m.materials?.length||0} 个材质<br>标准材质展示，不等于专属风格着色通过</p></details></div></article>`).join('')||'<p>此筛选下没有模型</p>';
 document.querySelectorAll('.stage').forEach(s=>{s.querySelector('.load').onclick=()=>enqueue(s);s.querySelector('.expand').onclick=()=>{enqueue(s);if(document.fullscreenElement)document.exitFullscreen();else s.requestFullscreen?.().catch(()=>$('#modelGrid').classList.add('large'))}});
 observe=new IntersectionObserver(entries=>entries.filter(e=>e.isIntersecting).forEach(e=>enqueue(e.target)),{rootMargin:'300px'});document.querySelectorAll('.stage').forEach(s=>observe.observe(s));
 // A selected subject always loads its six styles together, including off-screen cards.
 if(subject!=='all')document.querySelectorAll('.stage').forEach(enqueue);updateLoadStatus();
}
function enqueue(stage){if(active.some(x=>x.stage===stage)||queue.includes(stage))return;queue.push(stage);pump()}
function pump(){while(loading<2&&queue.length){const stage=queue.shift();if(!stage.isConnected)continue;loading++;const gen=epoch;loadModel(stage).finally(()=>{if(gen===epoch){loading--;updateLoadStatus();pump()}})}updateLoadStatus()}
function loadModel(stage){return new Promise(resolve=>{const m=data.models.find(x=>x.id===stage.dataset.id),b=stage.querySelector('.load');if(!m){resolve();return}const mv=document.createElement('model-viewer');mv.src=m.file;mv.alt=m.title;mv.setAttribute('camera-controls','');mv.setAttribute('touch-action','pan-y');mv.setAttribute('shadow-intensity','0.6');mv.setAttribute('camera-orbit',syncOrbit);mv.setAttribute('field-of-view','30deg');mv.setAttribute('interaction-prompt','none');mv.setAttribute('loading','eager');b.hidden=true;stage.classList.add('loading');stage.append(mv);const item={stage,mv,ready:false};active.push(item);let ended=false;let timer=setTimeout(()=>finish(false),45000);function finish(ok){if(ended)return;ended=true;clearTimeout(timer);stage.classList.remove('loading');if(ok){item.ready=true;stage.classList.add('ready')}else{mv.remove();b.hidden=false;b.textContent='载入失败 · 点击重试';active=active.filter(x=>x!==item)}resolve()};mv.addEventListener('load',()=>finish(true),{once:true});mv.addEventListener('error',()=>finish(false),{once:true});mv.addEventListener('model-visibility',e=>{if(e.detail.visible&&$('#sync').checked)mv.cameraOrbit=syncOrbit});mv.addEventListener('camera-change',e=>{if(e.detail.source!=='user-interaction'||!$('#sync').checked)return;const o=mv.getCameraOrbit();syncOrbit=`${o.theta}rad ${o.phi}rad auto`;syncSource=mv;if(syncFrame)return;syncFrame=requestAnimationFrame(()=>{syncFrame=0;for(const x of active){if(x.mv!==syncSource&&x.mv.modelIsVisible)x.mv.cameraOrbit=syncOrbit}})});})}
$('#resetCameras').onclick=()=>{syncOrbit='35deg 75deg auto';active.forEach(x=>{x.mv.cameraOrbit=syncOrbit;x.mv.fieldOfView='30deg'})};
$('#loadAll').onclick=()=>document.querySelectorAll('.stage').forEach(enqueue);$('#unload').onclick=releaseAll;$('#bigger').onclick=()=>{const on=$('#modelGrid').classList.toggle('large');$('#bigger').textContent=on?'标准大预览':'超大预览';};
 document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>{version=b.dataset.version;subject='all';drawNavigation();renderModels()});
 drawNavigation();renderModels();
const categories=[...new Set(data.images.map(i=>i.category))];categories.forEach(c=>$('#uiCategory').add(new Option(c,c)));function renderImages(){let q=$('#uiSearch').value.trim();let a=data.images.filter(i=>($('#uiCategory').value==='all'||i.category===$('#uiCategory').value)&&(!q||(i.title+' '+i.category).includes(q)));$('#uiGrid').innerHTML=a.map(i=>`<article class="card"><button class="image-open" data-image="${esc(i.file)}" data-title="${esc(i.title)}"><img src="${esc(i.file)}" alt="${esc(i.title)}" loading="lazy"></button><div class="card-body"><h3>${esc(i.title)}</h3><div class="meta"><span>${i.width} × ${i.height} 原生像素</span><span>${esc(i.category)}</span></div><p>${i.approved?'用户认可方向 · ':''}${esc(i.status||'设计候选 · 未实装验证')}</p></div></article>`).join('')||'<p>未找到匹配参考图</p>';}$('#uiCategory').onchange=renderImages;$('#uiSearch').oninput=renderImages;document.addEventListener('click',e=>{const b=e.target.closest('.image-open');if(!b)return;$('#largeImage').src=b.dataset.image;$('#largeImage').classList.remove('zoomed');$('#imageTitle').textContent=b.dataset.title;$('#imageDownload').href=b.dataset.image;$('#lightbox').showModal()});$('#largeImage').onclick=e=>e.target.classList.toggle('zoomed');$('#closeImage').onclick=()=>$('#lightbox').close();document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{releaseAll();if(b.dataset.tab==='models')renderModels();document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.panel').forEach(x=>x.hidden=x.id!==b.dataset.tab);$('#heading').textContent={models:'让差别，看得见',ui:'每个界面，保留原貌',progress:'睡后做了什么，直接打开测试',evidence:'完成到哪里，证据就到哪里'}[b.dataset.tab]});renderImages();
